import{_ as a,C as i,o as n,c as r,E as d,a2 as o}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Release I1.0","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu Implementation Case — Release I1.0","type":"implementation-case","domain":"TMPA","version":"I1.0","status":"stable-release","source":"github-main","related":["TMPA Architecture Paper","TMPA Core Specification","FCoP","CodeFlowMu"],"outline":"deep"},"headers":[],"relativePath":"en/publications/implementation-case-i1.0.md","filePath":"en/publications/implementation-case-i1.0.md","lastUpdated":1786439037000}'),s={name:"en/publications/implementation-case-i1.0.md"};function c(l,e,u,h,p,m){const t=i("ArticleCover");return n(),r("div",null,[d(t,{image:"/assets/covers/implementation-case.svg",kicker:"Engineering Case",title:"TMPA Implementation Case",summary:"An exact-input TMPA Core S1.0 product run and locked public evidence package for CodeFlowMu V1.8.0.",version:"I1.0",status:"Stable release · S1.0 product evidence · 14/14 PASS",languageHref:"/zh/publications/implementation-case-i1.0",languageLabel:"简体中文"}),e[0]||(e[0]=o(`<h1 id="tmpa-implementation-and-case-report" tabindex="-1">TMPA Implementation and Case Report <a class="header-anchor" href="#tmpa-implementation-and-case-report" aria-label="Permalink to &quot;TMPA Implementation and Case Report&quot;">​</a></h1><h2 id="tmpa-core-s1-0-fcop-codeflowmu-v1-8-0-and-retained-field-evidence" tabindex="-1">TMPA Core S1.0, FCoP, CodeFlowMu V1.8.0, and retained field evidence <a class="header-anchor" href="#tmpa-core-s1-0-fcop-codeflowmu-v1-8-0-and-retained-field-evidence" aria-label="Permalink to &quot;TMPA Core S1.0, FCoP, CodeFlowMu V1.8.0, and retained field evidence&quot;">​</a></h2><blockquote><p><strong>Document Version:</strong> I1.0<br><strong>Status:</strong> Official implementation and case report<br><strong>Normative Target:</strong> <a href="/joinwell52/en/publications/tmpa-core-specification-s1.0">TMPA Core Specification S1.0</a>, frozen candidate commit <code>942cbb097eb3d662662f96a2269818ec9d7ca2ed</code><br><strong>Product Under Test:</strong> CodeFlowMu V1.8.0, evidence commit <code>c1e1f724293e8048fc3a956b6f6df8cf83f54830</code><br><strong>Evidence Capture:</strong> 2026-08-11, Asia/Shanghai<br><strong>Formal Evidence Package:</strong> <code>tmpa-i1.0-codeflowmu-v1.8.0-s1.0-evidence-20260811.zip</code><br><strong>Package SHA-256:</strong> <code>9b92b06c3e46c8019362f55075be4ed066cb7a9c0d9859945b6c3b7de8840d04</code></p></blockquote><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>I1.0 evaluates CodeFlowMu V1.8.0 against all fourteen mandatory criteria in TMPA Core S1.0 using the exact bytes frozen by the normative candidate commit. The CodeFlowMu product path reports <strong>14 PASS, 0 PARTIAL, 0 NOT RUN, and 0 FAIL</strong>. The runner calls <code>GovernanceReader.readSync</code>; it does not call the TMPA Reference Reader. The input-bundle digest is <code>sha256:f98764987760cdc8ac356b1265fc98485f33345e7d6ffc8575ccb059ddd34daa</code>, and the result digest is <code>sha256:0f0f642449db1853371861751a7a8ea36dce00013f53e32012a5e4dae45f4c39</code>.</p><p>The evidence package fixes the S1.0 schemas, profiles, fixtures, product Adapter and Reader source, CodeFlowMu and FCoP revisions, dependency locks, raw command logs, pre-fix failures, final regression results, a reduced clean-machine reproducer, and a 889-entry SHA-256 manifest. The final regression record contains 24/24 TMPA Runtime tests, 1,522 passed / 0 failed / 1 skipped Runtime tests, 791/791 Shell tests, and 1,210 passed / 2 skipped FCoP reference-implementation tests.</p><p>The strongest supported conclusion is <strong>author-run demonstrated product behavior for one exact implementation and one exact S1.0 bundle</strong>. The result is not independent validation, third-party certification, universal conformance, proof of TMPA theory, proof of semantic truth, proof that hallucinations have been eliminated, or independent adoption.</p><h1 id="_1-scope-and-research-questions" tabindex="-1">1. Scope and Research Questions <a class="header-anchor" href="#_1-scope-and-research-questions" aria-label="Permalink to &quot;1. Scope and Research Questions&quot;">​</a></h1><p>I1.0 asks:</p><ol><li>Does the CodeFlowMu V1.8.0 product Reader satisfy S1.0 C01–C14 against the exact frozen input bundle?</li><li>Can the source revision, product revision, input bundle, per-criterion results, regression runs, and evidence archive be traced without substituting the Reference Reader?</li><li>Does the evidence package preserve pre-fix results and demonstrate a clean reproducer without weakening the S1.0 criteria?</li><li>Which findings are demonstrated, and which conclusions remain unsupported?</li></ol><p>The unit of judgment is a criterion-bound claim over a fixed bundle. Evidence maturity and conformance verdicts are reported separately:</p><table tabindex="0"><thead><tr><th>Evidence level</th><th>Meaning in I1.0</th><th style="text-align:right;">Reached?</th></tr></thead><tbody><tr><td>Specified</td><td>S1.0 clauses, schemas, profiles, and C01–C14 define the required behavior</td><td style="text-align:right;">Yes</td></tr><tr><td>Implemented</td><td>CodeFlowMu V1.8.0 contains the corresponding Adapter, Reader, protocol, and governance mechanisms</td><td style="text-align:right;">Yes</td></tr><tr><td>Demonstrated</td><td>Author-run product and regression executions produced inspectable evidence</td><td style="text-align:right;">Yes, for the fixed bundle and revision</td></tr><tr><td>Independently Adopted</td><td>An unrelated organization adopted and independently validated the mechanism</td><td style="text-align:right;">No</td></tr></tbody></table><h1 id="_2-architecture-and-evidence-boundaries" tabindex="-1">2. Architecture and Evidence Boundaries <a class="header-anchor" href="#_2-architecture-and-evidence-boundaries" aria-label="Permalink to &quot;2. Architecture and Evidence Boundaries&quot;">​</a></h1><p>The current guidance and implementation relation is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture Paper A1.0</span></span>
<span class="line"><span>        ↓ provides the architecture theory and design direction</span></span>
<span class="line"><span>TMPA Core Specification S1.0</span></span>
<span class="line"><span>        ↓ fixes normative object, Reader, and conformance behavior</span></span>
<span class="line"><span>FCoP protocol</span></span>
<span class="line"><span>        ↓ supplies the file-based coordination and evidence profile</span></span>
<span class="line"><span>CodeFlowMu V1.8.0</span></span>
<span class="line"><span>        ↓ implements and consumes the Adapter/Reader result</span></span>
<span class="line"><span>bounded cases, governance gates, recovery, and audit views</span></span></code></pre></div><p>TMPA is the theory and normative governance layer. FCoP is a reusable coordination protocol, not an application program. The <code>fcop</code> and <code>fcop-mcp</code> packages are reference implementations of FCoP rather than the protocol itself. CodeFlowMu is the engineering system guided by TMPA: it emits and consumes coordination evidence, projects FCoP artifacts into TMPA candidates, reconstructs a governance view, and lets workflow, review, recovery, and audit components consume the result.</p><p>Historical co-evolution is reported separately. XiaoDian AI, FCoP, CodeFlowMu, and TMPA share an author-controlled lineage; engineering feedback helped refine the present formalization. That lineage does not make an implementation a proof of the theory. WP-13 remains a bounded example of role-separated evidence admission and fact checking; it does not prove hallucination elimination and is not substituted for the S1.0 C01–C14 run.</p><h1 id="_3-fixed-sources-and-evidence-design" tabindex="-1">3. Fixed Sources and Evidence Design <a class="header-anchor" href="#_3-fixed-sources-and-evidence-design" aria-label="Permalink to &quot;3. Fixed Sources and Evidence Design&quot;">​</a></h1><h2 id="_3-1-locked-identities" tabindex="-1">3.1 Locked identities <a class="header-anchor" href="#_3-1-locked-identities" aria-label="Permalink to &quot;3.1 Locked identities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Fixed identity</th><th>Role in this report</th></tr></thead><tbody><tr><td>TMPA Core</td><td>S1.0 candidate commit <code>942cbb097eb3d662662f96a2269818ec9d7ca2ed</code></td><td>Normative input</td></tr><tr><td>CodeFlowMu</td><td>V1.8.0 evidence commit <code>c1e1f724293e8048fc3a956b6f6df8cf83f54830</code></td><td>Product under test</td></tr><tr><td>CodeFlowMu protocol surface</td><td>V1.2.0</td><td>Product schema and validator surface</td></tr><tr><td>FCoP reference implementation</td><td>commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code></td><td>Locked dependency regression only</td></tr><tr><td>Product Reader</td><td><code>GovernanceReader.readSync</code></td><td>Required execution path</td></tr><tr><td>Product Adapter</td><td><code>FcopSourceAdapter.projectFcopToTmpa</code></td><td>FCoP-to-TMPA projection path</td></tr></tbody></table><p>The product run used an isolated, tracked-clean evidence worktree. The original CodeFlowMu mother worktree was observed as dirty and changing, so it was not used as the evidentiary execution root. The V1.8.0 evidence commit was local-only at capture time: it was not pushed, tagged, or released. The complete source snapshot and V1.7.0-to-V1.8.0 patch are therefore included in the evidence archive. This supports inspection of the tested source but does not turn the commit into a public CodeFlowMu release.</p><h2 id="_3-2-fixed-machine-inputs" tabindex="-1">3.2 Fixed machine inputs <a class="header-anchor" href="#_3-2-fixed-machine-inputs" aria-label="Permalink to &quot;3.2 Fixed machine inputs&quot;">​</a></h2><p>The run locks four S1.0 JSON Schemas plus the lifecycle Profile, canonicalization Profile, fixtures, and input bundle identity. The four published Schema hashes are:</p><table tabindex="0"><thead><tr><th>Schema</th><th>SHA-256</th></tr></thead><tbody><tr><td>Governance object</td><td><code>a2829cd7149c3054a52886365f2293a23106b636b0c52799739bfabdab1ff4fa</code></td></tr><tr><td>Lifecycle Profile</td><td><code>481a61ac2485bbaf15d90e9c5a255ad9ce6a55971190f0fe404856be4b10f993</code></td></tr><tr><td>Reader result</td><td><code>4527df7096fe840b85b245e50d5cea576ff359d50a54d17c8873a7b4f458d431</code></td></tr><tr><td>Conformance result</td><td><code>4b1ecebf83e62d2aa1aff0e79a0cd0ea0a85fbc14a426d5fe873ab40aefdc2fe</code></td></tr></tbody></table><h2 id="_3-3-evidence-construction" tabindex="-1">3.3 Evidence construction <a class="header-anchor" href="#_3-3-evidence-construction" aria-label="Permalink to &quot;3.3 Evidence construction&quot;">​</a></h2><p>For each criterion, the product runner records a manifest, explicit mandatory assertions, product input invocations, canonical Reader output, assertion outcomes, a manifest digest, and a result digest. The aggregate result is validated against the S1.0 conformance-result Schema. Raw stdout, stderr, exit status, command, working directory, environment, dependency-lock digest, and remediation history are retained.</p><p>The frozen S1.0 candidate corpus also contains a historical product <code>NOT RUN</code> baseline. I1.0 does not rewrite it. The V1.8.0 product result is registered as a later external exact-version run so that candidate history and later evidence remain distinguishable.</p><h1 id="_4-executed-test-baseline" tabindex="-1">4. Executed Test Baseline <a class="header-anchor" href="#_4-executed-test-baseline" aria-label="Permalink to &quot;4. Executed Test Baseline&quot;">​</a></h1><p>The formal product command was <code>npm run test:tmpa:s1.0</code>. It executed the CodeFlowMu product Reader against the fixed bundle and produced the following aggregate:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Core: S1.0</span></span>
<span class="line"><span>Implementation: CodeFlowMu V1.8.0</span></span>
<span class="line"><span>Product Reader called: true</span></span>
<span class="line"><span>Reference Reader called: false</span></span>
<span class="line"><span>PASS: 14</span></span>
<span class="line"><span>PARTIAL: 0</span></span>
<span class="line"><span>NOT RUN: 0</span></span>
<span class="line"><span>FAIL: 0</span></span>
<span class="line"><span>Aggregate: PASS</span></span></code></pre></div><p>The S1.0 Reference Reader separately reports 14/14 PASS. Its result validates the author-produced reference path; it is not counted as a CodeFlowMu product result.</p><h1 id="_5-c01–c14-product-results" tabindex="-1">5. C01–C14 Product Results <a class="header-anchor" href="#_5-c01–c14-product-results" aria-label="Permalink to &quot;5. C01–C14 Product Results&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Criterion</th><th>Tested behavior</th><th style="text-align:right;">Mandatory assertions</th><th style="text-align:right;">Result</th></tr></thead><tbody><tr><td>C01</td><td>Schema validation and rejection of invalid shapes</td><td style="text-align:right;">3</td><td style="text-align:right;">PASS</td></tr><tr><td>C02</td><td>Primary-carrier and single-writer immutability</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C03</td><td>Duplicate identity handling with source provenance</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C04</td><td>Per-stream continuity and asynchronous progress</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C05</td><td>Role authority evaluation</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C06</td><td>Lifecycle legality and state preservation</td><td style="text-align:right;">9</td><td style="text-align:right;">PASS</td></tr><tr><td>C07</td><td>Separation of duties and human approval authorization</td><td style="text-align:right;">10</td><td style="text-align:right;">PASS</td></tr><tr><td>C08</td><td>Integrity tampering detection</td><td style="text-align:right;">3</td><td style="text-align:right;">PASS</td></tr><tr><td>C09</td><td>Missing-reference treatment</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C10</td><td>Prohibited-cycle detection</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C11</td><td>Aggregation and reconstruction determinism</td><td style="text-align:right;">4</td><td style="text-align:right;">PASS</td></tr><tr><td>C12</td><td>Conflict preservation and explicit resolution</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C13</td><td>Recovery behavior</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr><tr><td>C14</td><td>Terminal-history preservation</td><td style="text-align:right;">5</td><td style="text-align:right;">PASS</td></tr></tbody></table><p>The 71 recorded assertions were recomputed during publication review. All manifest digests, actual-result digests, input-bundle digest, and the aggregate conformance-result digest matched the package records.</p><h1 id="_6-s0-6-to-s1-0-engineering-delta" tabindex="-1">6. S0.6 to S1.0 Engineering Delta <a class="header-anchor" href="#_6-s0-6-to-s1-0-engineering-delta" aria-label="Permalink to &quot;6. S0.6 to S1.0 Engineering Delta&quot;">​</a></h1><h2 id="_6-1-stable-machine-identity" tabindex="-1">6.1 Stable machine identity <a class="header-anchor" href="#_6-1-stable-machine-identity" aria-label="Permalink to &quot;6.1 Stable machine identity&quot;">​</a></h2><p>S1.0 reissues the reviewed S0.6 behavior under stable S1.0 schema identifiers, Profile identities, canonicalization identity, and executable corpus paths. CodeFlowMu V1.8.0 binds its validator and Reader to those identities rather than treating an older-Core result as evidence for S1.0.</p><h2 id="_6-2-product-level-projection" tabindex="-1">6.2 Product-level projection <a class="header-anchor" href="#_6-2-product-level-projection" aria-label="Permalink to &quot;6.2 Product-level projection&quot;">​</a></h2><p>The product runner imports the exact S1.0 bundle, validates the lifecycle Profile through the CodeFlowMu protocol surface, creates the CodeFlowMu <code>GovernanceReader</code>, and passes FCoP-derived source candidates through the product path. The Reference Reader module is retained in the bundle for traceability but is not imported or called by the product runner.</p><h2 id="_6-3-regression-alignment-without-criterion-weakening" tabindex="-1">6.3 Regression alignment without criterion weakening <a class="header-anchor" href="#_6-3-regression-alignment-without-criterion-weakening" aria-label="Permalink to &quot;6.3 Regression alignment without criterion weakening&quot;">​</a></h2><p>The retained pre-fix Runtime run reported 1,520 passed, 2 failed, and 1 skipped. The failures were stale expectations for V1.7 wording and for the distinction between QA execution completion and a failing business verdict. Tests were aligned to the already implemented contract; no S1.0 schema, fixture, mandatory assertion, Reader behavior, or pass criterion was weakened.</p><p>A later isolated wake-endpoint failure passed five immediate repetitions. One full run also stalled in <code>TaskDispatcher.test.ts</code>; the exact child process was terminated, and a bounded audit then reported 29 passed / 0 failed. These records remain in the package rather than being erased.</p><h1 id="_7-regression-and-reproducer-results" tabindex="-1">7. Regression and Reproducer Results <a class="header-anchor" href="#_7-regression-and-reproducer-results" aria-label="Permalink to &quot;7. Regression and Reproducer Results&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Surface</th><th style="text-align:right;">Final result</th><th>Interpretation</th></tr></thead><tbody><tr><td>CodeFlowMu TMPA Runtime suite</td><td style="text-align:right;">24 passed / 0 failed</td><td>Product Reader unit and integration surface</td></tr><tr><td>CodeFlowMu Runtime full suite</td><td style="text-align:right;">1,522 passed / 0 failed / 1 skipped</td><td>Final full run</td></tr><tr><td>Runtime batched coverage</td><td style="text-align:right;">207/207 files; 1,522 passed / 0 failed / 1 skipped</td><td>Exact file coverage confirmation</td></tr><tr><td>CodeFlowMu Shell batched coverage</td><td style="text-align:right;">791 passed / 0 failed</td><td>Exact 8-batch execution</td></tr><tr><td>Protocol validation and typecheck</td><td style="text-align:right;">exit 0</td><td>Schema and validator surface</td></tr><tr><td>FCoP locked reference implementation</td><td style="text-align:right;">1,210 passed / 2 skipped</td><td>Dependency regression; not a substitute for product Reader</td></tr><tr><td>Reduced clean-machine reproducer</td><td style="text-align:right;">14/14 PASS</td><td><code>npm ci</code> plus exact S1.0 product runner</td></tr></tbody></table><p>The reproducer initially excluded an entire Protocol schemas directory and therefore also removed the required S1.0 schemas. That reduced-scope attempt is retained as a failure. The corrected reproducer excludes only unrelated legacy material, retains <code>schemas/tmpa</code>, installs from the lock file, and executes the same product runner successfully.</p><h1 id="_8-retained-wp-13-evidence-gating-case" tabindex="-1">8. Retained WP-13 Evidence-Gating Case <a class="header-anchor" href="#_8-retained-wp-13-evidence-gating-case" aria-label="Permalink to &quot;8. Retained WP-13 Evidence-Gating Case&quot;">​</a></h1><p>WP-13 is retained as a field-oriented example of multi-agent fact checking with executor/reviewer separation, evidence admission, audit records, and explicit lifecycle boundaries. Its evidence package supports the bounded conclusion that development completed and role-separated QA passed for the captured task state. It also records that later task snapshots were still <code>review</code> and <code>pending</code>, that a scheduled date was advanced without a separately located approval artifact, and that runtime binding and signed checksums were outside the package boundary.</p><p>WP-13 illustrates why TMPA separates execution evidence, review evidence, authorization, lifecycle state, and publication claims. It is not one of the S1.0 C01–C14 product fixtures. It does not prove the theory, independently validate CodeFlowMu, or prove that multi-agent systems cannot hallucinate.</p><h1 id="_9-three-valued-governance-interpretation" tabindex="-1">9. Three-Valued Governance Interpretation <a class="header-anchor" href="#_9-three-valued-governance-interpretation" aria-label="Permalink to &quot;9. Three-Valued Governance Interpretation&quot;">​</a></h1><p>TMPA keeps semantic judgment separate from view classification:</p><table tabindex="0"><thead><tr><th>Judgment</th><th>Typical view</th><th>Meaning</th></tr></thead><tbody><tr><td><code>valid</code></td><td>authoritative</td><td>Required evidence and applicable rules establish the conclusion.</td></tr><tr><td><code>invalid</code></td><td>quarantined / rejected</td><td>A deterministic violation excludes the affected evidence or action from authoritative use.</td></tr><tr><td><code>undetermined</code></td><td>partial / disputed / pending_human</td><td>Evidence is missing or conflicting, or an authorized human decision is still required.</td></tr></tbody></table><p>The V1.8.0 run makes this separation observable. A wrong-type, self-issued, or otherwise unauthorized approval remains preserved but cannot satisfy C07. A missing reference in C09 leaves the dependent claim <code>undetermined</code> rather than silently complete. An unauthorized resolution in C12 remains evidence but is <code>invalid</code> as a resolving act. Integrity failure in C08 quarantines the covered content while preserving its source record. These are governance judgments over evidence; they are not semantic truth judgments about the world.</p><h1 id="_10-evidence-integrity-and-publication-audit" tabindex="-1">10. Evidence Integrity and Publication Audit <a class="header-anchor" href="#_10-evidence-integrity-and-publication-audit" aria-label="Permalink to &quot;10. Evidence Integrity and Publication Audit&quot;">​</a></h1><p>The formal archive contains 891 entries and 889 files. All 889 files are covered by its internal SHA-256 manifest, and the outer ZIP SHA-256 is <code>9b92b06c3e46c8019362f55075be4ed066cb7a9c0d9859945b6c3b7de8840d04</code>. Publication audit verified:</p><ul><li>safe ZIP paths and structural integrity;</li><li>889/889 internal SHA-256 entries;</li><li>strict UTF-8 decoding for 884 text files;</li><li>successful parsing of all 190 JSON files;</li><li>byte identity for the four published S1.0 Schemas and the remaining normative inputs;</li><li>product Reader invocation without Reference Reader substitution;</li><li>Schema-valid C01–C14 result envelopes;</li><li>recomputation of all fourteen manifest digests, fourteen result digests, 71 mandatory assertions, the aggregate result digest, and the input-bundle digest;</li><li>preservation of pre-fix failures, remediation notes, raw commands, exit status, dependency locks, source snapshot, and patch.</li></ul><p>No recomputed digest or assertion differed from the archive record. This audit establishes internal consistency and traceability of the submitted package; it is not an independent product rerun or certification.</p><h1 id="_11-limitations" tabindex="-1">11. Limitations <a class="header-anchor" href="#_11-limitations" aria-label="Permalink to &quot;11. Limitations&quot;">​</a></h1><ol><li>The product and regression evidence is author-run. No independent organization has certified or adopted the implementation.</li><li>The CodeFlowMu evidence commit was local-only at capture time and was not a public tag or release. The archive carries a complete source snapshot and patch for inspection.</li><li>The evidence worktree was tracked-clean, but the original mother worktree was dirty and changing. Claims are bound to the isolated evidence worktree and fixed commit.</li><li>The reduced reproducer demonstrates the conformance slice, not every private deployment dependency or operational environment of CodeFlowMu.</li><li>Runtime retains one skipped test; the FCoP reference implementation retains two skipped tests. Neither skip is counted as a C01–C14 product result.</li><li>C11 evaluates a fixed fixture set and declared permutations; it is not a formal proof over arbitrary graphs, encodings, filesystems, or hostile platforms.</li><li>C08 demonstrates governance-object integrity handling, not model truthfulness, actor authentication, installer integrity, or Byzantine resilience.</li><li>Full-suite performance, representative SME burden, comparative baselines, cross-profile portability, and independent deployment remain open empirical questions.</li><li>WP-13 is a bounded governance and evidence-admission case, not a hallucination-elimination benchmark.</li></ol><h1 id="_12-claim-ledger" tabindex="-1">12. Claim Ledger <a class="header-anchor" href="#_12-claim-ledger" aria-label="Permalink to &quot;12. Claim Ledger&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Claim</th><th>I1.0 disposition</th></tr></thead><tbody><tr><td>TMPA Core S1.0 defines C01–C14</td><td><strong>Specified</strong></td></tr><tr><td>CodeFlowMu V1.8.0 contains corresponding product mechanisms</td><td><strong>Implemented</strong></td></tr><tr><td>The exact product bundle records 14/14 PASS</td><td><strong>Demonstrated</strong></td></tr><tr><td>The archive preserves inputs, source, commands, outputs, failures, and hashes</td><td><strong>Demonstrated</strong></td></tr><tr><td>The reduced conformance slice ran successfully in the captured clean reproducer</td><td><strong>Demonstrated</strong></td></tr><tr><td>CodeFlowMu is universally conformant for arbitrary inputs and deployments</td><td><strong>Not claimed</strong></td></tr><tr><td>The result has been independently rerun, certified, or adopted</td><td><strong>Not demonstrated</strong></td></tr><tr><td>TMPA theory is proved by the implementation</td><td><strong>Prohibited conclusion</strong></td></tr><tr><td>WP-13 proves hallucination elimination</td><td><strong>Prohibited conclusion</strong></td></tr></tbody></table><h1 id="_13-engineering-conclusion" tabindex="-1">13. Engineering Conclusion <a class="header-anchor" href="#_13-engineering-conclusion" aria-label="Permalink to &quot;13. Engineering Conclusion&quot;">​</a></h1><p>I1.0 establishes a release-grade, exact-input engineering baseline for TMPA Core S1.0. CodeFlowMu V1.8.0 passes all fourteen mandatory criteria through its own product Adapter and Reader path, records 71 mandatory assertions, and preserves the regression, remediation, source, dependency, and integrity trail needed to inspect the result. The S1.0 frozen candidate baseline and the later product execution remain separately identifiable.</p><p>The result strengthens evidence that TMPA can guide a concrete engineering system. It does not make CodeFlowMu the authority that defines TMPA, and it does not convert engineering success into proof of the theory. The dependency direction remains: A1.0 states the architecture theory; S1.0 defines normative behavior; FCoP supplies the coordination protocol; CodeFlowMu implements and consumes the governance projection; I1.0 reports the bounded evidence.</p><h1 id="artifact-availability" tabindex="-1">Artifact Availability <a class="header-anchor" href="#artifact-availability" aria-label="Permalink to &quot;Artifact Availability&quot;">​</a></h1><p>The formal archive is <a href="/joinwell52/evidence/tmpa/i1.0/tmpa-i1.0-codeflowmu-v1.8.0-s1.0-evidence-20260811.zip">tmpa-i1.0-codeflowmu-v1.8.0-s1.0-evidence-20260811.zip</a>. The adjacent file <code>tmpa-i1.0-codeflowmu-v1.8.0-s1.0-evidence-20260811.zip.sha256</code> records <code>9b92b06c3e46c8019362f55075be4ed066cb7a9c0d9859945b6c3b7de8840d04</code>.</p><p>The run is registered in the <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s1.0/external-runs/20260811-codeflowmu-v1.8.0" target="_blank" rel="noreferrer">S1.0 external-run registry</a>. Earlier I0.6–I0.8 packages remain immutable historical evidence at their versioned paths. Git history is the publication history; no parallel paper database has editorial authority.</p><h1 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h1><p>[1] TMPA Project. “TMPA Core Specification S1.0,” frozen candidate commit <code>942cbb097eb3d662662f96a2269818ec9d7ca2ed</code>. GitHub, 2026.</p><p>[2] TMPA Project. “TMPA Architecture Paper A1.0.” GitHub, 2026.</p><p>[3] FCoP Project. “FCoP — File-based Coordination Protocol,” reference implementation commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code>. GitHub, 2026.</p><p>[4] CodeFlowMu Project. “CodeFlowMu V1.8.0 S1.0 Product Conformance,” evidence commit <code>c1e1f724293e8048fc3a956b6f6df8cf83f54830</code>, 2026.</p><p>[5] TMPA Project. “I1.0 CodeFlowMu V1.8.0 S1.0 Evidence,” package <code>tmpa-i1.0-codeflowmu-v1.8.0-s1.0-evidence-20260811</code>, 2026.</p><p>[6] CodeFlowMu Project. “WP-13 Multi-Agent Fact-Check Publication Evidence V3,” 2026.</p><p>[7] CodeFlowMu Project. “TMPA Governance: Theory-to-Engineering Relation,” <code>docs/TMPA-GOVERNANCE.md</code>. GitHub, 2026. <code>https://github.com/joinwell52-AI/codeflowmu/blob/main/docs/TMPA-GOVERNANCE.md</code>.</p>`,74))])}const b=a(s,[["render",c]]);export{f as __pageData,b as default};
